import test from 'node:test';
import assert from 'node:assert/strict';
import { recordPayment, balanceDue } from '../src/payments.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

// balanceDue tests
test('balanceDue equals total for unpaid issued invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  // Total should be 48854 (42500 - 2125 discount + 8479 VAT)
  const balance = balanceDue(issued);
  assert.equal(balance, 48854);
});

test('balanceDue decreases after a payment', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = recordPayment(issued, { amount: 10000, date: '2026-10-15' });
  assert.equal(r3.ok, true);
  const afterPayment = r3.value;

  const balance = balanceDue(afterPayment);
  assert.equal(balance, 38854);
});

test('balanceDue is zero for fully paid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = recordPayment(issued, { amount: 48854, date: '2026-10-15' });
  assert.equal(r3.ok, true);
  const afterPayment = r3.value;

  const balance = balanceDue(afterPayment);
  assert.equal(balance, 0);
});

test('balanceDue on invoice without payments array', () => {
  const inv = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21, discountPercent: 5 }],
  };

  const balance = balanceDue(inv);
  assert.equal(balance, 48854);
});

// recordPayment tests
test('recordPayment records a single payment', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = recordPayment(issued, { amount: 10000, date: '2026-10-15' });
  assert.equal(r3.ok, true);
  const afterPayment = r3.value;
  assert.equal(afterPayment.payments.length, 1);
  assert.equal(afterPayment.payments[0].amount, 10000);
  assert.equal(afterPayment.payments[0].date, '2026-10-15');
});

test('recordPayment creates payments array if missing', () => {
  const inv = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21, discountPercent: 5 }],
  };

  const r = recordPayment(inv, { amount: 10000, date: '2026-10-15' });
  assert.equal(r.ok, true);
  assert.ok(Array.isArray(r.value.payments));
  assert.equal(r.value.payments.length, 1);
});

test('recordPayment changes status from issued to partially_paid', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;
  assert.equal(issued.status, 'issued');

  const r3 = recordPayment(issued, { amount: 10000, date: '2026-10-15' });
  const afterPayment = r3.value;
  assert.equal(afterPayment.status, 'partially_paid');
});

test('recordPayment changes status to paid when fully paid', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = recordPayment(issued, { amount: 48854, date: '2026-10-15' });
  assert.equal(r3.ok, true);
  const afterPayment = r3.value;
  assert.equal(afterPayment.status, 'paid');
});

test('recordPayment accepts multiple payments', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = recordPayment(issued, { amount: 20000, date: '2026-10-15' });
  assert.equal(r3.ok, true);
  const afterPayment1 = r3.value;
  assert.equal(afterPayment1.status, 'partially_paid');

  const r4 = recordPayment(afterPayment1, { amount: 28854, date: '2026-10-20' });
  assert.equal(r4.ok, true);
  const afterPayment2 = r4.value;
  assert.equal(afterPayment2.payments.length, 2);
  assert.equal(afterPayment2.status, 'paid');
});

test('recordPayment reports NOT_ISSUED for draft status', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = recordPayment(inv, { amount: 10000, date: '2026-10-15' });
  assert.deepEqual(r2, { ok: false, error: 'NOT_ISSUED' });
});

test('recordPayment reports NOT_ISSUED for already paid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = recordPayment(issued, { amount: 48854, date: '2026-10-15' });
  const paid = r3.value;

  const r4 = recordPayment(paid, { amount: 1000, date: '2026-10-20' });
  assert.deepEqual(r4, { ok: false, error: 'NOT_ISSUED' });
});

test('recordPayment reports AMOUNT_INVALID for non-integer amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = recordPayment(issued, { amount: 10000.5, date: '2026-10-15' });
  assert.deepEqual(r3, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment reports AMOUNT_INVALID for zero amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = recordPayment(issued, { amount: 0, date: '2026-10-15' });
  assert.deepEqual(r3, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment reports AMOUNT_INVALID for negative amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = recordPayment(issued, { amount: -1000, date: '2026-10-15' });
  assert.deepEqual(r3, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment reports OVERPAYMENT', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = recordPayment(issued, { amount: 48855, date: '2026-10-15' });
  assert.deepEqual(r3, { ok: false, error: 'OVERPAYMENT' });
});

test('recordPayment reports OVERPAYMENT on partially paid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = recordPayment(issued, { amount: 20000, date: '2026-10-15' });
  const partial = r3.value;

  const r4 = recordPayment(partial, { amount: 28855, date: '2026-10-20' });
  assert.deepEqual(r4, { ok: false, error: 'OVERPAYMENT' });
});

test('recordPayment does not mutate original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;
  const originalStatus = issued.status;

  recordPayment(issued, { amount: 10000, date: '2026-10-15' });
  assert.equal(issued.status, originalStatus);
  assert.equal(issued.payments, undefined);
});

test('recordPayment preserves other invoice fields', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = recordPayment(issued, { amount: 10000, date: '2026-10-15' });
  const afterPayment = r3.value;
  assert.equal(afterPayment.customerId, 'C-001');
  assert.equal(afterPayment.issueDate, '2026-10-07');
  assert.equal(afterPayment.number, issued.number);
  assert.deepEqual(afterPayment.lines, issued.lines);
});

test('recordPayment works on invoice with no discount', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  const r3 = recordPayment(issued, { amount: 51425, date: '2026-10-15' });
  assert.equal(r3.ok, true);
  const afterPayment = r3.value;
  assert.equal(afterPayment.status, 'paid');
});

test('recordPayment works with complex invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const inv = r.value;
  const r2 = issueInvoice(inv, []);
  const issued = r2.value;

  // Make a partial payment
  const r3 = recordPayment(issued, { amount: 50000, date: '2026-10-15' });
  assert.equal(r3.ok, true);
  assert.equal(r3.value.status, 'partially_paid');

  // Make another partial payment
  const r4 = recordPayment(r3.value, { amount: 50000, date: '2026-10-20' });
  assert.equal(r4.ok, true);
  assert.equal(r4.value.status, 'partially_paid');

  // Final payment
  const balance = balanceDue(r4.value);
  const r5 = recordPayment(r4.value, { amount: balance, date: '2026-10-25' });
  assert.equal(r5.ok, true);
  assert.equal(r5.value.status, 'paid');
  assert.equal(r5.value.payments.length, 3);
});

test('recordPayment accepts partially_paid status', () => {
  const inv = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21, discountPercent: 5 }],
    payments: [{ amount: 10000, date: '2026-10-15' }],
  };

  const r = recordPayment(inv, { amount: 20000, date: '2026-10-20' });
  assert.equal(r.ok, true);
  assert.equal(r.value.payments.length, 2);
});

